class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) { super.onCreate(savedInstanceState); setContent { VeloraTheme { VeloraApp() } } }
}

enum class Screen { Splash, Login, Register, Onboarding, Discover, Detail, Match, Matches, Chats, Chat, Profile, Settings, Premium }
data class Person(val name:String, val age:Int, val city:String, val distance:String, val bio:String, val image:Int, val online:Boolean=true)
val maya = Person("Maya",27,"Lisbon","3 km","Slow mornings, hidden cafés and spontaneous flights. Looking for something beautifully real.",R.drawable.maya)
val sofia = Person("Sofia",29,"Porto","8 km","Art director. Sunset swimmer. I will always order dessert for the table.",R.drawable.sofia)

@Composable fun VeloraApp() {
    var screen by remember { mutableStateOf(Screen.Splash) }
    var previous by remember { mutableStateOf(Screen.Discover) }
    LaunchedEffect(Unit) { delay(1100); screen = Screen.Login }
    val go: (Screen)->Unit = { previous=screen; screen=it }
    CompositionLocalProvider(LocalContentColor provides White) { Box(Modifier.fillMaxSize().background(Ink)) {
        AnimatedContent(screen, transitionSpec={ fadeIn(tween(260)) togetherWith fadeOut(tween(180)) }, label="screen") { s ->
            when(s) {
                Screen.Splash -> Splash()
                Screen.Login -> Login(onCreate={go(Screen.Register)}, onLogin={go(Screen.Discover)})
                Screen.Register -> Register(onBack={go(Screen.Login)}, onContinue={go(Screen.Onboarding)})
                Screen.Onboarding -> Onboarding(onDone={go(Screen.Discover)})
                Screen.Discover -> MainShell(s, go) { Discover(onDetail={go(Screen.Detail)}, onMatch={go(Screen.Match)}) }
                Screen.Detail -> ProfileDetail(maya, onBack={screen=previous}, onMatch={go(Screen.Match)})
                Screen.Match -> MatchScreen(onChat={go(Screen.Chat)}, onContinue={go(Screen.Discover)})
                Screen.Matches -> MainShell(s, go) { Matches(onChat={go(Screen.Chat)}) }
                Screen.Chats -> MainShell(s, go) { Chats(onChat={go(Screen.Chat)}) }
                Screen.Chat -> Chat(onBack={go(Screen.Chats)})
                Screen.Profile -> MainShell(s, go) { MyProfile(onSettings={go(Screen.Settings)}, onPremium={go(Screen.Premium)}) }
                Screen.Settings -> Settings(onBack={go(Screen.Profile)}, onLogout={go(Screen.Login)})
                Screen.Premium -> Premium(onBack={go(Screen.Profile)})
            }
        }
    } }
}

